?><header class="site-header"><nav class="navbar"><a class="logo" href="/smart-toolz/"><span class="logo-icon">🛠️</span><span>SmartToolz</span></a><button class="menu-button" type="button" aria-label="Menu" aria-expanded="false">☰</button><div class="nav-links"><a href="/smart-toolz/">Home</a><a href="/smart-toolz/tool.php">All Tools</a><?php if($isLoggedIn): ?><a href="/smart-toolz/account.php" class="nav-dashboard">My Account</a><a href="/creator-ai/">AI Dashboard</a><a class="nav-user" href="/smart-toolz/account.php"><?php if($displayAvatar!==''): ?><img src="<?=htmlspecialchars($displayAvatar,ENT_QUOTES,'UTF-8')?>" alt=""><?php else: ?><span><?=htmlspecialchars($initial,ENT_QUOTES,'UTF-8')?></span><?php endif; ?><strong><?=htmlspecialchars($displayName?:'Account',ENT_QUOTES,'UTF-8')?></strong></a><a href="/creator-ai/auth/logout.php">Logout</a><?php else: ?><a class="login-btn" href="/creator-ai/auth/google-login.php">Login with Google</a><?php endif; ?></div></nav></header><style>.site-header{position:sticky;top:0;z-index:1000;background:rgba(255,255,255,.96);backdrop-filter:blur(16px);border-bottom:1px solid #e7eaf1}.navbar{width:min(1400px,calc(100% - 28px));min-height:72px;margin:auto;display:flex;align-items:center;justify-content:space-between;gap:22px;position:relative}.logo{display:flex;align-items:center;gap:10px;color:#172033;font-size:21px;font-weight:850;text-decoration:none;white-space:nowrap}.logo-icon{width:42px;height:42px;display:grid;place-items:center;border-radius:13px;color:#fff;background:linear-gradient(135deg,#635bff,#916cff)}.nav-links{display:flex;align-items:center;gap:18px}.nav-links a{color:#596477;font-size:13px;font-weight:700;text-decoration:none}.nav-links a:hover{color:#635bff}.nav-dashboard{color:#635bff!important}.login-btn{padding:10px 15px;border-radius:11px;color:#fff!important;background:#635bff}.nav-user{display:flex;align-items:center;gap:7px!important}.nav-user img,.nav-user>span{width:30px;height:30px;border-radius:50%;object-fit:cover}.nav-user>span{display:grid;place-items:center;background:#635bff;color:#fff;font-size:12px}.menu-button{display:none;border:0;background:transparent;font-size:27px;cursor:pointer}@media(max-width:820px){.menu-button{display:block}.nav-links{display:none;position:absolute;top:64px;left:0;right:0;padding:12px;flex-direction:column;align-items:stretch;background:#fff;border:1px solid #e7eaf1;border-top:0;border-radius:0 0 16px 16px;box-shadow:0 18px 35px #141c321a}.nav-links.open{display:flex}.nav-links a{padding:10px}.nav-user{justify-content:flex-start}}</style><script>(()=>{const b=document.querySelector('.menu-button'),n=document.querySelector('.nav-links');if(b&&n)b.onclick=()=>{const o=n.classList.toggle('open');b.setAttribute('aria-expanded',o?'true':'false')};const r=new URLSearchParams(location.search).get('ref');if(r&&/^[A-Za-z0-9_-]{4,40}$/.test(r)){document.cookie='smarttoolz_ref='+encodeURIComponent(r)+';path=/;max-age=2592000;Secure;SameSite=Lax';}<?php if($isLoggedIn): ?>fetch('/smart-toolz/saas/claim-ref.php',{credentials:'same-origin'}).catch(()=>{});
const creditState={busy:false,bypass:false};
const generationPattern=/^(generate|create|process|calculate|convert|compress|merge|split|make|encode|decode|resize|crop|rotate|remove|format|optimize|download\s+(?:pdf|jpg|jpeg|png|webp|gif))/i;
async function smartToolzSpendCredit(button){if(creditState.busy||creditState.bypass)return true;const label=(button.textContent||'').trim();if(!generationPattern.test(label))return true;creditState.busy=true;const old=button.textContent;button.disabled=true;button.textContent='Checking credits…';try{const body=new URLSearchParams({tool:(location.pathname.split('/').pop()||'tool').replace(/\.php$/,'')});const res=await fetch('/smart-toolz/saas/credits.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},credentials:'same-origin',body});if(res.status===401){location.href='/creator-ai/auth/google-login.php';return false}const data=await res.json();if(!data.ok){alert(data.message||'No credits remaining.');location.href='/smart-toolz/account.php';return false}button.textContent='Starting…';creditState.bypass=true;button.click();creditState.bypass=false;return false}catch(e){alert('Could not verify your credits. Please try again.');return false}finally{creditState.busy=false;if(document.body.contains(button)){button.disabled=false;if(button.textContent==='Checking credits…'||button.textContent==='Starting…')button.textContent=old}}}
document.addEventListener('click',e=>{const btn=e.target.closest?.('button');if(!btn||creditState.bypass)return;const label=(btn.textContent||'').trim();if(generationPattern.test(label)){e.preventDefault();e.stopImmediatePropagation();smartToolzSpendCredit(btn)}},true);
<?php endif; ?>})();</script>
